def drive(me, enemy, arena):
    # If the robot is on its side or end, it cannot drive.
    if me.on_side:
        return None

    # Calculate relative position and bearing to the enemy.
    bearing = bearing_to(enemy.x, enemy.y)
    dist = distance_to(enemy.x, enemy.y)

    # Strategy:
    # 1. Long range: Turn toward the enemy and charge to close the gap.
    # 2. Short range: Orbit the enemy to avoid the front flipper and hit the sides.

    if dist > 3.0:
        # Long range: Charge forward
        if abs(bearing) > 10:
            # Turn toward enemy while moving forward
            turn_dir = 1 if bearing > 0 else -1
            return (0.7 * turn_dir, -0.7 * turn_dir) if abs(bearing) > 45 else (0.5 * turn_dir, -0.5 * turn_dir)
        else:
            return (1.0, 1.0)
    else:
        # Short range: Orbiting logic
        # We target a bearing offset to keep the flipper from facing us directly.
        # We choose a target bearing based on which side the enemy is on.
        target_bearing = 30 if bearing > 0 else -30
        bearing_error = bearing - target_bearing

        if abs(bearing_error) > 5:
            # Turn to correct the bearing while maintaining forward momentum
            turn_dir = 1 if bearing_error > 0 else -1
            # Mix forward movement with differential steering to orbit
            return (0.5 + 0.5 * turn_dir, 0.5 - 0.5 * turn_dir)
        else:
            # Maintain the orbital path
            return (0.6, 0.6)

