    if me.on_side:
        return None

    # Calculate relative position and bearing to the enemy.
    bearing = bearing_to(enemy.x, enemy.y)
    dist = distance_to(enemy.x, enemy.y)

    # Strategy against a flipper:
    # 1. Avoid head-on collisions to prevent being flipped.
    # 2. Orbit the enemy to strike the sides/back with the vertical spinner.

    # If we are flipped, we can still drive because we are invertible.
    if me.inverted:
        if dist < 2.0:
            # Move away to regain control and avoid immediate re-flipping
            return (-0.5, -0.5)
        else:
            # Turn and approach from an angle
            target_bearing = 30
            bearing_error = bearing - target_bearing
            turn_dir = 1 if bearing_error > 0 else -1
            return (0.5 * turn_dir, -0.5 * turn_dir) if abs(bearing_error) > 10 else (0.7, 0.7)

    if dist > 3.0:
        # Long range: Approach the enemy with an offset to avoid the flipper.
        target_bearing = 20
        bearing_error = bearing - target_bearing

        if abs(bearing_error) > 10:
            # Turn toward the target bearing while moving forward.
            turn_dir = 1 if bearing_error > 0 else -1
            return (0.6 * turn_dir, -0.6 * turn_dir) if abs(bearing_error) > 45 else (0.4 * turn_dir, -0.4 * turn_dir)
        else:
            return (1.0, 1.0)
    else:
        # Short range: Orbiting logic.
        # Target bearing 45 degrees (front-left) to strike the enemy's side.
        target_bearing = 45
        bearing_error = bearing - target_bearing

        if abs(bearing_error) > 15:
            # Correct the bearing.
            turn_dir = 1 if bearing_error > 0 else -1
            # Combine forward movement with turning to maintain an orbital path.
            return (0.3 + 0.7 * turn_dir, 0.3 - 0.7 * turn_dir)
        else:
            # Maintain the orbit with a steady forward speed.
            return (0.8, 0.8)

